#!/usr/bin/env python3
"""Stage 8c T3: writes S0_ROUND3_DECISION.md from results/loop_S0_ours.json, results/preview_S0_ours.json (read only). Numbers only from the files."""
import json, math
from pathlib import Path
H = Path(__file__).resolve().parent; R = H / 'results'
r = json.load(open(R / 'loop_S0_ours.json')); pv = json.load(open(R / 'preview_S0_ours.json')); rd = r['rounds']
NAMES = ['Pxy', 'Pz', 'Dxy', 'Dz', 'Iz', 'KRxy', 'KRz', 'Kwxy', 'Kwz', 'KIxy']
cm = lambda f: 100 * f['cost'] ** 0.5
L = ['# S0 "ours": round 3 decision sheet (facts only; the user decides)', '', 'Source: `results/loop_S0_ours.json`, `results/preview_S0_ours.json`, thresholds from `make_lab_tomorrow.py` lines 23–25, `lab/round.py`, `loop_lib.py`. Generated by `make_s0_round3_sheet.py`.', '',
     '## 1. Real cost per scenario (cm, 3-D RMS, one flight each) and gains', '', '| Scenario | round 2 (θ₂) | round 3 (θ₃) | round 4 (θ₄) |', '|---|---|---|---|']
for i, f in enumerate(rd[2]['flights']):
    s = f['scenario']; v = [next(g for g in rd[l]['flights'] if g['scenario'] == s) for l in (2, 3, 4)]
    L.append('| %s | %s |' % (s, ' | '.join('%.2f%s' % (cm(g), ' (floor)' if g['floor'] else '') for g in v)))
L.append('| **mean (rms3d_cm)** | %s |' % ' | '.join('%.2f' % rd[l]['real']['rms3d_cm'] for l in (2, 3, 4)))
f3 = [math.exp(a - b) for a, b in zip(rd[3]['phi'], rd[2]['phi'])]; f4 = [math.exp(a - b) for a, b in zip(rd[4]['phi'], rd[3]['phi'])]
L += ['', 'Gain factors (flown set against the previous flown set; the per-round limit is ±25 %, i.e. 0.75 … 1.25):', '', '| | ' + ' | '.join(NAMES) + ' |', '|---|' + '---|' * 10,
      '| θ₃ / θ₂ | ' + ' | '.join('%.2f' % x for x in f3) + ' |', '| θ₄ / θ₃ | ' + ' | '.join('%.2f' % x for x in f4) + ' |', '']
r_ = [x['real']['rms3d_cm'] for x in rd]; n = len(r_)
fl = [{f['scenario']: bool(f['crashed'] or f['floor']) for f in x['flights']} for x in rd]
viol_b = [(l, s) for l in range(1, n) for s in fl[l] if fl[l][s] and not (fl[0][s] and fl[1][s])]
L += ['## 2. Why criteria a and b fail', '',
      '* a (`make_lab_tomorrow.py:23`): real cost of every round l ≥ 2 must be ≤ cost of round 1 + 1.0 cm = %.2f + 1.00 = %.2f cm. Rounds: %s. Violations: %s.' % (r_[1], r_[1] + 1, ', '.join('%d: %.2f' % (l, r_[l]) for l in range(2, n)), ', '.join('round %d (%.2f)' % (l, r_[l]) for l in range(2, n) if r_[l] > r_[1] + 1.0) or 'none'),
      '* b (`make_lab_tomorrow.py:24–25`): a crashed or floor flight in round l ≥ 1 is a violation unless that scenario also failed in rounds 0 and 1. Violations (round, scenario): %s. Round 0 floor flights: %s; round 1: %s.' % (viol_b, [s for s in fl[0] if fl[0][s]], [s for s in fl[1] if fl[1][s]]),
      '* Both violations come from one flight: A1 in round 3 (%.2f cm, floor). No crash in any round.' % cm(next(g for g in rd[3]['flights'] if g['scenario'] == 'A1')), '']
b = r['best']
L += ['## 3. What keep-best returns, and round 3\'s influence', '',
      '* Keep-best (`loop_S0_ours.json` → `best`): round %d, real cost %.2f cm (θ_best = θ₅, a flown set; selection by flown real cost only).' % (b['round'], 100 * b['cost'] ** 0.5),
      '* The selection does not use round 3\'s cost. But θ₄ was computed at the end of round 3 from round 3\'s flights (fit of β, then tuning step), and θ₅ from round 4 starting at that β and θ₄; so round 3\'s flights, A1 floor flight included (see §4), fed the chain that produced θ₄ and θ₅. Whether θ₅ would differ without them: not tested (no run without round 3 exists).',
      '* Round 3 fit: %d epochs (%s), `seconds_fit` %.0f s; the fit of round 3 comes after the flight of θ₃ and does not change it.' % (rd[3]['fit']['epochs'], rd[3]['fit']['reason'], rd[3]['seconds_fit']), '']
L += ['## 4. Lab protocol against the dry run (floor flights)', '',
      '* Lab rule (`docs/diffcotune_lab_protocol_S0_DRAFT.md` line 34; `lab/round.py` header line 17): a crashed, tilted or floor flight is not used and is repeated, at most 2 repeats (attempt ≤ 3). With `--lenient` (dry / mock tests only, `round.py --lenient` help text) floor flights are fitted; a real round keeps the strict rule (`strict=not a.lenient`).',
      '* Dry run (`loop_lib.py`, `floor_failed` docstring: "Reported for every flight; it does not trigger a repeat (only the tilt rule does)"): the floor flag is only recorded. A1 in round 0 (%.2f cm) and round 3 (%.2f cm) were **fitted** in the dry run; in the lab they would have been repeated and not used for the fit. What the fit and the later θ would have been without them: not tested.' % (cm(next(g for g in rd[0]['flights'] if g['scenario'] == 'A1')), cm(next(g for g in rd[3]['flights'] if g['scenario'] == 'A1'))),
      '* Protocol note (draft line 38): "In the plant run, the default gains on A1 fail (floor) in every run. The sim fit uses that flight. In the lab it would be repeated and not used, so the lab round 0 can differ from the sim (open)."',
      '* What a repeated A1 flight at θ₃ would give in the lab: not stated (the repeat would use the same θ₃).', '',
      '## 5. Safety preview per round', '', '| Round | preview | real cost (cm) | notes |', '|---|---|---|---|']
for x in pv:
    L.append('| %d | %s | %.2f | fails: %s; notes worse: %s |' % (x['round'], 'PASSED' if x['preview']['passed'] else 'FAILED', x['real_cm'], x['preview']['fails'], x['preview']['notes_worse']))
L += ['', 'Reading from the report §6: round 2 FAILED but improved (false alarm); round 3 PASSED but A1 became a floor flight (missed: the model plant with the fitted β is not the true plant).', '',
      '## 6. Options (no recommendation; the user decides)', '', '* **A** Accept S0 "ours" as it is: criteria a and b stay "no", reason documented (single A1 floor flight in round 3, recovered in rounds 4–5; held-out A4 cell 2 %.2f → %.2f cm, see `results/eval_S0_ours.json`).' % (
          [e for e in json.load(open(R / 'eval_S0_ours.json'))['eval']['theta_0'] if e['role'] == 'test' and e['scenario'] == 'A4'] and sum(e['rms3d_cm'] for e in json.load(open(R / 'eval_S0_ours.json'))['eval']['theta_0'] if e['role'] == 'test' and e['scenario'] == 'A4') / 5,
          sum(e['rms3d_cm'] for e in json.load(open(R / 'eval_S0_ours.json'))['eval']['theta_best'] if e['role'] == 'test' and e['scenario'] == 'A4') / 5),
      '* **B** A criterion that tolerates a floor / worse round that later recovers: needs a definition by the user (not defined here; no criterion is changed).',
      '* **C** Other (user).']
(H / 'S0_ROUND3_DECISION.md').write_text('\n'.join(L) + '\n'); print('\n'.join(L))
